// @ts-ignore `.open-next/worker.js` is generated by the Cloudflare build.
import generatedWorker from "./.open-next/worker.js";
import { getRetiredLegacyProductRedirect } from "./src/lib/catalog-legacy-redirects";
import { getStagingAdminEntryRedirect } from "./src/lib/admin-host-redirect";
import { deliverQueuedLead, type LeadDeliveryEnvironment, type LeadDeliveryMessage } from "./src/lib/lead-delivery-worker";
import { deliverQueuedZaloSale } from "./src/lib/zalo-sale-delivery-worker";
import type { ZaloSaleDeliveryMessage as ZaloSaleQueueMessage } from "./src/lib/zalo-sale-queue";
import { deliverCustomerContact, type CustomerContactDeliveryEnvironment, type CustomerContactDeliveryMessage } from "./src/lib/customer-contact-delivery";

interface WorkerEnv extends LeadDeliveryEnvironment, CustomerContactDeliveryEnvironment {
  GIACONG_VN_CATALOG?: CatalogDatabase;
}

type WorkerQueueMessage = (LeadDeliveryMessage & { type?: undefined }) | ZaloSaleQueueMessage | CustomerContactDeliveryMessage;

interface CatalogPreparedStatement {
  all<T = Record<string, unknown>>(): Promise<{ results: T[] }>;
  bind(...values: unknown[]): CatalogPreparedStatement;
  first<T = Record<string, unknown>>(): Promise<T | null>;
  run(): Promise<unknown>;
}

interface CatalogDatabase {
  prepare(query: string): CatalogPreparedStatement;
}

interface QueueMessage<T> {
  attempts: number;
  body: T;
  retry(options?: { delaySeconds?: number }): void;
}

interface QueueBatch<T> {
  messages: QueueMessage<T>[];
  queue: string;
}

interface WorkerExecutionContext {
  passThroughOnException(): void;
  waitUntil(promise: Promise<unknown>): void;
}

const nonIndexableHosts = new Set([
  "admin-staging.kienhieu.id.vn",
  "admin.kienhieu.id.vn",
  "staging.kienhieu.id.vn",
]);

const publicDocumentHosts = new Set(["kienhieu.id.vn", "staging.kienhieu.id.vn"]);
const publicDocumentHostByAdminHost = new Map([
  ["admin.kienhieu.id.vn", "kienhieu.id.vn"],
  ["admin-staging.kienhieu.id.vn", "staging.kienhieu.id.vn"],
]);
const PUBLIC_DOCUMENT_CACHE_CONTROL = "public, max-age=0, s-maxage=600, stale-while-revalidate=3600";
const STAGING_DOCUMENT_CACHE_CONTROL = "public, max-age=0, s-maxage=600, stale-while-revalidate=3600";
const CDN_DOCUMENT_CACHE_CONTROL = "public, max-age=86400, stale-while-revalidate=604800";
const STAGING_CDN_DOCUMENT_CACHE_CONTROL = "public, max-age=600";
const PUBLIC_DOCUMENT_CACHE_VERSION = "2026-10-12-next-16-3-8";
const publicDocumentCache = (caches as CacheStorage & { default: Cache }).default;

function publicDocumentCacheHostname(hostname: string): string | null {
  const normalizedHostname = hostname.toLowerCase();
  if (publicDocumentHosts.has(normalizedHostname)) return normalizedHostname;
  return publicDocumentHostByAdminHost.get(normalizedHostname) ?? null;
}

function isPublicDocumentRequest(request: Request): boolean {
  if (request.method !== "GET") return false;

  const url = new URL(request.url);
  if (!publicDocumentHosts.has(url.hostname.toLowerCase())) return false;
  if (!(request.headers.get("Accept") ?? "").includes("text/html")) return false;
  if (request.headers.has("RSC") || url.searchParams.has("_rsc")) return false;
  if (
    request.headers.has("Cookie") ||
    request.headers.has("Authorization") ||
    request.headers.has("cf-access-jwt-assertion")
  ) return false;
  if (url.pathname === "/api" || url.pathname.startsWith("/api/")) return false;
  if (["/admin", "/tai-khoan", "/gui-yeu-cau"].some((path) => url.pathname === path || url.pathname.startsWith(`${path}/`))) {
    return false;
  }

  const normalizedUrl = new URL(url);
  for (const param of Array.from(normalizedUrl.searchParams.keys())) {
    if (MARKETING_QUERY_PARAMS.has(param.toLowerCase())) normalizedUrl.searchParams.delete(param);
  }
  if (normalizedUrl.searchParams.size > 0) return false;
  return true;
}

function isPublicDocumentResponse(response: Response): boolean {
  if (response.status !== 200) return false;
  if (!(response.headers.get("Content-Type") ?? "").includes("text/html")) return false;
  return !response.headers.has("Set-Cookie");
}

function withPublicDocumentCache(request: Request, response: Response): Response {
  if (!isPublicDocumentRequest(request) || !isPublicDocumentResponse(response)) return response;

  const staging = new URL(request.url).hostname.toLowerCase() === "staging.kienhieu.id.vn";
  const headers = new Headers(response.headers);
  headers.set("Cache-Control", staging ? STAGING_DOCUMENT_CACHE_CONTROL : PUBLIC_DOCUMENT_CACHE_CONTROL);
  headers.set("CDN-Cache-Control", staging ? STAGING_CDN_DOCUMENT_CACHE_CONTROL : CDN_DOCUMENT_CACHE_CONTROL);
  headers.delete("Pragma");
  headers.delete("Expires");
  return new Response(response.body, {
    headers,
    status: response.status,
    statusText: response.statusText,
  });
}

function withStagingDocumentCacheStatus(request: Request, response: Response, status: "HIT" | "MISS"): Response {
  if (new URL(request.url).hostname.toLowerCase() !== "staging.kienhieu.id.vn") return response;
  const headers = new Headers(response.headers);
  if (status === "HIT") headers.set("Cache-Control", "no-store");
  headers.set("X-Storefront-Document-Cache", status);
  return new Response(response.body, {
    headers,
    status: response.status,
    statusText: response.statusText,
  });
}

const MARKETING_QUERY_PARAMS = new Set([
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "fbclid",
  "gclid",
  "gad_source",
  "zarsrc",
  "ref",
  "mc_cid",
  "mc_eid",
]);

function publicDocumentCacheKey(request: Request): Request {
  const url = new URL(request.url);
  for (const param of Array.from(url.searchParams.keys())) {
    if (MARKETING_QUERY_PARAMS.has(param.toLowerCase())) {
      url.searchParams.delete(param);
    }
  }
  url.searchParams.set("__document_cache_version", PUBLIC_DOCUMENT_CACHE_VERSION);
  return new Request(url.toString(), { method: "GET" });
}

const DOCUMENT_STORE_CACHE_CONTROL = "public, max-age=604800";
const DOCUMENT_FRESH_MS = 600_000;
const DOCUMENT_CACHED_AT_HEADER = "x-document-cached-at";

interface CachedPublicDocument {
  response: Response;
  stale: boolean;
}

async function readPublicDocumentCache(request: Request): Promise<CachedPublicDocument | null> {
  if (!isPublicDocumentRequest(request)) return null;
  try {
    const cached = await publicDocumentCache.match(publicDocumentCacheKey(request));
    if (!cached) return null;
    const storedAt = Number(cached.headers.get(DOCUMENT_CACHED_AT_HEADER));
    const stale = !Number.isFinite(storedAt) || Date.now() - storedAt > DOCUMENT_FRESH_MS;
    const staging = new URL(request.url).hostname.toLowerCase() === "staging.kienhieu.id.vn";
    const headers = new Headers(cached.headers);
    headers.delete(DOCUMENT_CACHED_AT_HEADER);
    headers.set("Cache-Control", staging ? STAGING_DOCUMENT_CACHE_CONTROL : PUBLIC_DOCUMENT_CACHE_CONTROL);
    headers.set("CDN-Cache-Control", staging ? STAGING_CDN_DOCUMENT_CACHE_CONTROL : CDN_DOCUMENT_CACHE_CONTROL);
    return {
      response: new Response(cached.body, { headers, status: cached.status, statusText: cached.statusText }),
      stale,
    };
  } catch (error) {
    console.warn("Public document cache read unavailable.", error);
    return null;
  }
}

async function storePublicDocument(request: Request, response: Response): Promise<void> {
  try {
    const headers = new Headers(response.headers);
    headers.set("Cache-Control", DOCUMENT_STORE_CACHE_CONTROL);
    headers.delete("CDN-Cache-Control");
    headers.set(DOCUMENT_CACHED_AT_HEADER, String(Date.now()));
    await publicDocumentCache.put(
      publicDocumentCacheKey(request),
      new Response(response.body, { headers, status: response.status, statusText: response.statusText }),
    );
  } catch (error) {
    console.warn("Public document cache write unavailable.", error);
  }
}

function writePublicDocumentCache(
  request: Request,
  response: Response,
  ctx: WorkerExecutionContext,
): void {
  if (!isPublicDocumentRequest(request) || !isPublicDocumentResponse(response)) return;
  ctx.waitUntil(storePublicDocument(request, response.clone()));
}

async function revalidatePublicDocument(
  request: Request,
  env: WorkerEnv,
  ctx: WorkerExecutionContext,
): Promise<void> {
  try {
    const fresh = await generatedWorker.fetch(new Request(request.url, { method: "GET", headers: request.headers }), env, ctx);
    const checked = await withCatalogProductNotFoundStatus(request, fresh, env);
    if (checked.status !== 200) return;
    const finalResponse = withPublicDocumentCache(request, withIndexingHeaders(request, checked));
    if (!isPublicDocumentResponse(finalResponse)) return;
    await storePublicDocument(request, finalResponse);
  } catch (error) {
    console.warn("Public document revalidation failed; keeping the cached copy.", error);
  }
}

function shouldPreventIndexing(request: Request): boolean {
  return nonIndexableHosts.has(new URL(request.url).hostname.toLowerCase());
}

function withIndexingHeaders(request: Request, response: Response): Response {
  if (!shouldPreventIndexing(request)) return response;
  const headers = new Headers(response.headers);
  headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
  return new Response(response.body, {
    headers,
    status: response.status,
    statusText: response.statusText,
  });
}

function catalogProductSlug(pathname: string): string | null {
  const match = /^\/san-pham\/([^/]+)\/?$/.exec(pathname);
  if (!match?.[1]) return null;
  try {
    const slug = decodeURIComponent(match[1]).trim();
    return slug || null;
  } catch {
    return null;
  }
}

async function getPublicCatalogProductTarget(database: CatalogDatabase, slug: string): Promise<string | null | undefined> {
  try {
    const row = await database.prepare(`
      SELECT products.slug AS slug
      FROM products
      LEFT JOIN product_slug_redirects
        ON product_slug_redirects.product_id = products.id
        AND product_slug_redirects.old_slug = ?
      WHERE products.is_active = 1
        AND (products.slug = ? OR product_slug_redirects.old_slug = ?)
      ORDER BY CASE WHEN products.slug = ? THEN 0 ELSE 1 END
      LIMIT 1
    `).bind(slug, slug, slug, slug).first<{ slug: string }>();
    return row?.slug ?? null;
  } catch (error) {
    try {
      // Older databases may not have the additive redirect table yet.
      const row = await database.prepare(
        "SELECT slug FROM products WHERE slug = ? AND is_active = 1 LIMIT 1",
      ).bind(slug).first<{ slug: string }>();
      return row?.slug ?? null;
    } catch (fallbackError) {
      console.error("Catalog visibility lookup failed.", {
        error,
        fallbackError,
      });
      return undefined;
    }
  }
}

async function withCatalogProductNotFoundStatus(
  request: Request,
  response: Response,
  env: WorkerEnv,
): Promise<Response> {
  if ((request.method !== "GET" && request.method !== "HEAD") || response.status !== 200) return response;

  const slug = catalogProductSlug(new URL(request.url).pathname);
  if (!slug || !env.GIACONG_VN_CATALOG) return response;

  const targetSlug = await getPublicCatalogProductTarget(env.GIACONG_VN_CATALOG, slug);
  if (targetSlug === undefined) return response;
  if (targetSlug === null) {
    const headers = new Headers(response.headers);
    return new Response(response.body, {
      headers,
      status: 404,
      statusText: "Not Found",
    });
  }
  if (targetSlug !== slug) {
    const location = new URL(request.url);
    location.pathname = `/san-pham/${encodeURIComponent(targetSlug)}/`;
    return withIndexingHeaders(
      request,
      new Response(null, { headers: { Location: location.toString() }, status: 308 }),
    );
  }

  return response;
}

const worker = {
  async fetch(request: Request, env: WorkerEnv, ctx: WorkerExecutionContext): Promise<Response> {
    const adminEntryRedirect = getStagingAdminEntryRedirect(request);
    if (adminEntryRedirect) {
      return withIndexingHeaders(request, new Response(null, {
        status: 307,
        headers: { Location: adminEntryRedirect, "Cache-Control": "no-store" },
      }));
    }
    if (request.method === "GET" || request.method === "HEAD") {
      const redirect = getRetiredLegacyProductRedirect(new URL(request.url));
      if (redirect) {
        return withIndexingHeaders(
          request,
          new Response(null, { headers: { Location: redirect }, status: 308 }),
        );
      }
    }

    const cachedEntry = await readPublicDocumentCache(request);
    if (cachedEntry) {
      const cachedDocument = cachedEntry.response;
      const checkedDocument = await withCatalogProductNotFoundStatus(request, cachedDocument, env);
      if (checkedDocument.status === 404) {
        ctx.waitUntil(
          publicDocumentCache.delete(publicDocumentCacheKey(request)).catch(() => {}),
        );
        return checkedDocument;
      }
      if (checkedDocument.status === 308) return checkedDocument;
      if (cachedEntry.stale) ctx.waitUntil(revalidatePublicDocument(request, env, ctx));
      if (new URL(request.url).hostname.toLowerCase() === "staging.kienhieu.id.vn") {
        return withStagingDocumentCacheStatus(request, cachedDocument, "HIT");
      }
      return cachedDocument;
    }

    const response = await generatedWorker.fetch(request, env, ctx);

    if (response.headers.has("x-purge-storefront-cache")) {
      const purgePaths = (response.headers.get("x-purge-storefront-cache") ?? "/")
        .split(",")
        .map((path: string) => path.trim())
        .filter(Boolean);
      for (const purgePath of purgePaths) {
        const requestUrl = new URL(request.url);
        const cacheHostname = publicDocumentCacheHostname(requestUrl.hostname);
        if (!cacheHostname) continue;
        const normalizedPaths = new Set<string>();
        normalizedPaths.add(purgePath);
        if (purgePath !== "/" && purgePath.endsWith("/")) {
          normalizedPaths.add(purgePath.slice(0, -1));
        } else if (purgePath !== "/" && !purgePath.endsWith("/")) {
          normalizedPaths.add(`${purgePath}/`);
        }
        for (const p of normalizedPaths) {
          const purgeUrl = new URL(p, requestUrl);
          purgeUrl.hostname = cacheHostname;
          const purgeKey = publicDocumentCacheKey(new Request(purgeUrl, { method: "GET" }));
          ctx.waitUntil(
            publicDocumentCache.delete(purgeKey).catch((error: unknown) => {
              console.warn("Public document cache delete failed.", error);
            }),
          );
        }
      }
      const cleanedHeaders = new Headers(response.headers);
      cleanedHeaders.delete("x-purge-storefront-cache");
      return new Response(response.body, {
        headers: cleanedHeaders,
        status: response.status,
        statusText: response.statusText,
      });
    }

    const catalogResponse = await withCatalogProductNotFoundStatus(request, response, env);
    const finalResponse = withPublicDocumentCache(
      request,
      withIndexingHeaders(request, catalogResponse),
    );
    writePublicDocumentCache(request, finalResponse, ctx);
    return isPublicDocumentRequest(request) && isPublicDocumentResponse(finalResponse)
      ? withStagingDocumentCacheStatus(request, finalResponse, "MISS")
      : finalResponse;
  },

  /** Keep-warm cron: loads the Next runtime and touches D1 so real visitors rarely hit a cold start. */
  async scheduled(_event: unknown, env: WorkerEnv, ctx: WorkerExecutionContext): Promise<void> {
    const warmPaths = ["/tai-khoan/dang-nhap/", "/lien-he/", "/san-pham/"];
    await Promise.all(
      warmPaths.map(async (path) => {
        try {
          const response = await generatedWorker.fetch(
            new Request(`https://kienhieu.id.vn${path}`, { headers: { Accept: "text/html" } }),
            env,
            ctx,
          );
          await response.arrayBuffer();
        } catch (error) {
          console.warn("Keep-warm request failed.", error instanceof Error ? error.message : "unknown_error");
        }
      }),
    );
  },

  async queue(batch: QueueBatch<WorkerQueueMessage>, env: WorkerEnv): Promise<void> {
    if (!env.GIACONG_VN_CATALOG) throw new Error("Missing GIACONG_VN_CATALOG binding.");
    for (const message of batch.messages) {
      try {
        if (message.body.type === "customer-contact") {
          await deliverCustomerContact(message.body.customerId, env, env.GIACONG_VN_CATALOG);
        } else if (message.body.type === "zalo-sale") {
          await deliverQueuedZaloSale(
            { saleId: message.body.saleId },
            env,
            env.GIACONG_VN_CATALOG,
            message.attempts <= 3,
          );
        } else {
          await deliverQueuedLead(message.body, env, env.GIACONG_VN_CATALOG);
        }
      } catch (error) {
        message.retry({ delaySeconds: 60 });
        if (message.body.type === "customer-contact") {
          console.error("Customer contact delivery pending; check the D1 delivery record.");
        } else if (message.body.type === "zalo-sale") {
          console.error("Zalo sale queue delivery failed.", {
            error: error instanceof Error ? error.message : "unknown_error",
            saleId: message.body.saleId,
            queue: batch.queue,
          });
        } else {
          console.error("Lead queue delivery failed.", {
            error: error instanceof Error ? error.message : "unknown_error",
            leadId: message.body.leadId,
            queue: batch.queue,
          });
        }
      }
    }
  },
};

export default worker;
